import warnings

import numpy as np
import pandas as pd
from pandas.core.util.hashing import hash_array, hash_pandas_object

# Bind every name the scenarios use (the descriptions reference bare `nan`).
nan = np.nan

# ---------------------------------------------------------------- description 1
name1 = "hash_pandas_object(pd.Series(np.array([np.sqrt(-1.)]))).values[0] compared with hash_pandas_object(pd.Series([np.nan])).values[0]"
try:
    with np.errstate(all="ignore"), warnings.catch_warnings():
        warnings.simplefilter("ignore")
        left = hash_pandas_object(pd.Series(np.array([np.sqrt(-1.)]))).values[0]
    right = hash_pandas_object(pd.Series([np.nan])).values[0]
    probe(
        name1,
        {
            "sqrt(-1.)": int(left),
            "np.nan": int(right),
            "equal": bool(left == right),
        },
    )
except Exception as e:
    probe_exception(name1, e)

# ---------------------------------------------------------------- description 2
name2 = "hash_array(np.array([0.0, -0.0], dtype=dtype)) for dtype in ['float16','float32','float64']"
try:
    result2 = {}
    for dtype in ['float16', 'float32', 'float64']:
        result2[dtype] = hash_array(np.array([0.0, -0.0], dtype=dtype)).tolist()
    probe(name2, result2)
except Exception as e:
    probe_exception(name2, e)

# ---------------------------------------------------------------- description 3
name3 = "hash_array(np.array([complex(nan, -0.0), complex(-nan, 0.0)], dtype=dtype)) for dtype in ['complex64','complex128']"
try:
    result3 = {}
    for dtype in ['complex64', 'complex128']:
        result3[dtype] = hash_array(
            np.array([complex(nan, -0.0), complex(-nan, 0.0)], dtype=dtype)
        ).tolist()
    probe(name3, result3)
except Exception as e:
    probe_exception(name3, e)

# ---------------------------------------------------------------- description 4
name4 = "hash_array(np.array([complex(0.0, 0.0), complex(-0.0, -0.0)], dtype=dtype)) for dtype in ['complex64','complex128']"
try:
    result4 = {}
    for dtype in ['complex64', 'complex128']:
        result4[dtype] = hash_array(
            np.array([complex(0.0, 0.0), complex(-0.0, -0.0)], dtype=dtype)
        ).tolist()
    probe(name4, result4)
except Exception as e:
    probe_exception(name4, e)

